#include <stdio.h>

/* maiorDeDois le dois inteiros digitados e imprime o maior dos dois.
   A leitura (scanf) e a impressao (printf) ja estao escritas.
   Troque o 0 da linha do meio: guarde em maior o maior entre a e b, com a
   condicao que devolve — pergunta, depois o ?, depois os dois valores. */
void maiorDeDois(void) {
    int a = 0;
    int b = 0;

    scanf("%d %d", &a, &b);

    int maior = 0;

    printf("%d\n", maior);
}

