#include <stdio.h>

/* teste do desafio maior-de-dois — counter_protocol (03-tdd 3.9.3).
   O main e o relatorio sao do harness; aqui so existem cenarios SM_TEST.
   Cada cenario escreve num arquivo o que a pessoa "digitaria", aponta o
   stdin para esse arquivo (freopen) e captura o stdout no proprio teste.
   Os nomes dos arquivos temporarios sao POR CENARIO: um cenario nunca le a
   entrada nem a captura do outro. Nunca ha fclose de stdin/stdout — so
   fflush — para o segundo freopen ficar legal (C11 7.21.4).
   As duas saidas esperadas sao DIFERENTES (9 e 12): um printf com numero
   fixo no codigo reprova num dos dois cenarios. */

/* prototipo da funcao do aluno (o teste declara o que exercita) */
void maiorDeDois(void);

SM_TEST(o_maior_vem_depois) {
    /* o que a pessoa digita: 3 e 9 — o maior e o SEGUNDO */
    FILE *e = fopen("sm_entrada_1.tmp", "w");
    fprintf(e, "3 9\n");
    fclose(e);
    freopen("sm_entrada_1.tmp", "r", stdin);

    /* captura: o stdout vira o arquivo sm_saida_1.tmp */
    freopen("sm_saida_1.tmp", "w", stdout);
    maiorDeDois();
    fflush(stdout);

    FILE *f = fopen("sm_saida_1.tmp", "r");
    char linha[80] = "(nada impresso)";
    fgets(linha, 80, f);
    checa_str("entre 3 e 9 o maior e 9", linha, "9\n",
              "a pergunta 3 > 9 deu falso, entao o lado do : foi devolvido");
    /* a saida TERMINA na primeira linha — buffer novo com sentinel */
    char fim[80] = "(nada impresso)";
    fgets(fim, 80, f);
    checa_str("nao ha linha a mais", fim, "(nada impresso)",
              "a saida e uma linha so: o maior, e nada mais");
    fclose(f);
}

SM_TEST(o_maior_vem_antes) {
    /* outra ordem e outro resultado: 12 e 5 — o maior e o PRIMEIRO */
    FILE *e = fopen("sm_entrada_2.tmp", "w");
    fprintf(e, "12 5\n");
    fclose(e);
    freopen("sm_entrada_2.tmp", "r", stdin);

    freopen("sm_saida_2.tmp", "w", stdout);
    maiorDeDois();
    fflush(stdout);

    FILE *f = fopen("sm_saida_2.tmp", "r");
    char linha[80] = "(nada impresso)";
    fgets(linha, 80, f);
    checa_str("entre 12 e 5 o maior e 12", linha, "12\n",
              "com o maior na frente a pergunta deu verdadeiro e o lado do ? foi devolvido");
    fclose(f);
}

